-- Ejecutar en la base nueva. Incluye datos del volcado antiguo.
-- Mantiene la contraseña cifrada antigua y omite fichajes ya existentes.
SET NAMES utf8mb4;
SET @zona_horaria_anterior = @@SESSION.time_zone;
SET time_zone = '+00:00';
CREATE TEMPORARY TABLE IF NOT EXISTS importacion_fichajes_temporal (
 id_antiguo BIGINT UNSIGNED NOT NULL PRIMARY KEY, usuario_antiguo BIGINT UNSIGNED NOT NULL,
 entrada TIMESTAMP NOT NULL, salida TIMESTAMP NULL, creado TIMESTAMP NULL, actualizado TIMESTAMP NULL
) ENGINE=InnoDB;
TRUNCATE TABLE importacion_fichajes_temporal;

-- 1. Crear Carmen si no existe, conservando su contraseña anterior.
START TRANSACTION;
SELECT 'Carmen María Catalán Usero', 'carmencu5@gmail.com', '$2y$12$YUiEjWZwIEDMzns.WimKbuM3UXt4Fx/8BmjlZL0rqfPrXA7jf8DYO', 'employee', 'Diseñadora Web', 5.00, 1, '50617936L', '141045113231', '2026-04-01 22:31:20', '2026-04-01 22:31:20'
WHERE NOT EXISTS (SELECT 1 FROM users WHERE email = 'carmencu5@gmail.com');

-- 2. Fichajes históricos: usuario antiguo 5 = Juan Antonio, 6 = Carmen.

-- Si falta alguno de los dos usuarios, no importa ningún fichaje.
SELECT u.id, f.entrada, f.salida, f.creado, f.actualizado
FROM importacion_fichajes_temporal f
JOIN users u ON u.email = CASE f.usuario_antiguo WHEN 5 THEN 'bymarquezz2@gmail.com' WHEN 6 THEN 'carmencu5@gmail.com' END
WHERE EXISTS (SELECT 1 FROM users WHERE email = 'bymarquezz2@gmail.com')
  AND EXISTS (SELECT 1 FROM users WHERE email = 'carmencu5@gmail.com')
  AND NOT EXISTS (SELECT 1 FROM attendance_records a WHERE a.user_id = u.id AND a.started_at = f.entrada AND a.ended_at <=> f.salida);
SET @fichajes_insertados = ROW_COUNT();
COMMIT;
SELECT @fichajes_insertados AS fichajes_insertados,
 (SELECT COUNT(*) FROM users WHERE email = 'bymarquezz2@gmail.com') AS usuario_juan_encontrado,
 (SELECT COUNT(*) FROM users WHERE email = 'carmencu5@gmail.com') AS usuario_carmen_encontrado;
SELECT u.name, COUNT(*) AS fichajes_historicos_presentes
FROM importacion_fichajes_temporal f
JOIN users u ON u.email = CASE f.usuario_antiguo WHEN 5 THEN 'bymarquezz2@gmail.com' WHEN 6 THEN 'carmencu5@gmail.com' END
JOIN attendance_records a ON a.user_id = u.id AND a.started_at = f.entrada AND a.ended_at <=> f.salida
GROUP BY u.id, u.name;
DROP TEMPORARY TABLE importacion_fichajes_temporal;
SET time_zone = @zona_horaria_anterior;
